// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = process.env.BUCKET || process.env.RELEASE_BUCKET || "";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function bucketBaseUrl(bucket) {
  if (/^https?:\/\//i.test(bucket)) {
    return bucket.replace(/\/+$/, "");
  }
  return `https://${bucket}.s3.amazonaws.com`;
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }

  const url = `${bucketBaseUrl(BUCKET)}/${name}`;
  const response = await fetch(url, {
    method: "PUT",
    headers: {
      "Content-Type": "application/javascript",
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`upload failed: ${response.status} ${response.statusText}`);
  }

  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});

arguments.command:
node -e '
const http = require("http");
const { spawn } = require("child_process");
let received = null;
const server = http.createServer((req, res) => {
  const chunks = [];
  req.on("data", c => chunks.push(c));
  req.on("end", () => {
    received = { method: req.method, url: req.url, body: Buffer.concat(chunks).toString() };
    res.writeHead(200, {"Content-Type": "text/plain"});
    res.end("ok");
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const child = spawn("node", ["upload.js"], {
    cwd: process.cwd(),
    env: { ...process.env, BUCKET: `http://127.0.0.1:${port}` }
  });
  child.stdout.pipe(process.stdout);
  child.stderr.pipe(process.stderr);
  child.on("exit", (code) => {
    console.log(JSON.stringify(received));
    server.close();
    process.exit(code);
  });
});
'
